head.script:
scwin.screenId = "jldods70003";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70003.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_openDocumentPop_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_openDocumentPop_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_openDocumentPop_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.openDocumentPop('cd')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70003.btn_openDocumentPop_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.openDocumentPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param gb
 * @returns
 * @hidden N
*/
scwin.openDocumentPop = async function (gb) {
    /* sdd-asis-lifecycle:begin openDocumentPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    dAction = "";
    if (gb === "wd") {
        dAction = "/discls/searchDisclosureDocument.do?method=searchWritingDocument";
    } else {
        dAction = "/discls/searchDisclosureDocument.do?method=searchCompleteDocument";
    }
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('disclsVal', dAction) : console.warn('[sdd] hiddenStore 부재: disclsVal'));
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(dAction));
    const pageURL = '/jldods70207/jldods70207.xml';
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(pageURL), { id: "disclsPage", width: "770", height: "480", scrollbars: true, resizable: false, type: "pageFramePopup" }, { method: "disclsConfirmInputPop" });
    /* sdd-asis-lifecycle:end */
};
